function toDateKey(dt){
 if(!dt)return "";
 try{const s=String(dt).slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(s)?s:"";}
 catch{return "";}
}
function nowDT(){
 // heure locale de l'appareil (l'ancien passage par toLocaleString "en-CA" donnait "NaN-NaN-NaN" sur iPhone)
 const p=v=>String(v).padStart(2,"0");
 const d=new Date();
 return d.getFullYear()+"-"+p(d.getMonth()+1)+"-"+p(d.getDate())+"T"+p(d.getHours())+":"+p(d.getMinutes());
}
const localYMD=d=>d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
function calcProfit(status,stake,odds){
 stake=Number(String(stake??0).replace(",","."))||0;odds=Number(String(odds??0).replace(",","."))||0;
 if(status==="won")return stake*(odds-1);
 if(status==="lost")return -stake;
 return 0;
}
// Profit d'un pari réparti sur plusieurs bookmakers : chaque part avec SA cote (b.stake = total)
function betProfit(b,status=b.status,stake=b.stake,odds=b.odds){
 const sp=b.splits||[];if(!sp.length)return calcProfit(status,Number(stake)||0,Number(odds)||0);
 const spSt=sp.reduce((t,x)=>t+(Number(x.stake)||0),0);
 const legs=[{stake:Math.max(0,(Number(stake)||0)-spSt),odds:Number(odds)||0},...sp.map(x=>({stake:Number(x.stake)||0,odds:Number(x.odds)||Number(odds)||0}))];
 return legs.reduce((t,l)=>t+calcProfit(status,l.stake,l.odds),0);
}





// NumPad 
function NumPad({value,onChange,placeholder,step,id}){
 const isDecimal=step==="0.01"||step==="0.5"||step==="1"; // all fields allow decimals
 return(
 <div style={{position:"relative"}}>
 <input
 id={id}
 type="text"
 inputMode="decimal"
 placeholder={placeholder}
 value={value||""}
 onChange={e=>{
 // Accept both . and , as decimal separator
 let v=e.target.value.replace(/,/g,".");
 v=v.replace(/[^0-9.]/g,"");
 const parts=v.split(".");
 if(parts.length>2)return;
 onChange(v);
 }}
 onBlur={e=>{
 // Convert shorthand odds only (e.g. 175 → 1.75) — NOT for stake fields (step="1")
 if(step==="1")return;
 if(step!=="0.01")return;
 let v=e.target.value.replace(/,/g,".").replace(/[^0-9.]/g,"");
 if(v&&!v.includes(".")&&parseInt(v)>=100){
 onChange((parseInt(v)/100).toFixed(2));
 }
 }}
 style={{
 width:"100%",
 background:"transparent",
 WebkitAppearance:"none",
 MozAppearance:"textfield",
 border:"none",
 padding:"12px 14px",
 color:value?"#eef3ff":"#5a6478",
 fontSize:20,
 fontFamily:"'Inter',system-ui,sans-serif",
 fontWeight:value?700:400,
 outline:"none",
 boxSizing:"border-box",
 paddingRight:value?42:14,
 WebkitTextFillColor:value?"#E5E7EB":"#6B7280",
 }}
 />
 {value&&(
 <button onMouseDown={e=>{e.preventDefault();onChange("");}}
 style={{position:"absolute",right:12,top:"50%",transform:"translateY(-50%)",background:"rgba(255,255,255,0.1)",border:"none",borderRadius:"50%",width:22,height:22,color:"rgba(255,255,255,0.5)",cursor:"pointer",fontSize:13,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"Inter"}}>
 ×
 </button>
 )}
 </div>
 );
}

// PlayerAC 
// Récents: stockés dans localStorage "v7_recent_players" (max 6)
function getRecentPlayers(){try{return JSON.parse(localStorage.getItem("v7_recent_players")||"[]");}catch(e){return[];}}
function addRecentPlayer(key){
 try{
 const prev=getRecentPlayers().filter(k=>k!==key);
 localStorage.setItem("v7_recent_players",JSON.stringify([key,...prev].slice(0,6)));
 }catch(e){}
}

const tourAbbr=n=>{const s=String(n||"").trim();if(/^esl/i.test(s))return "ESL";if(/^blast/i.test(s))return "Blast";if(/^pgl/i.test(s))return "PGL";if(/^iem/i.test(s))return "IEM";if(/^lck/i.test(s))return "LCK";if(/^lec/i.test(s))return "LEC";if(/^lpl/i.test(s))return "LPL";if(/^vct/i.test(s))return "VCT";if(/world/i.test(s))return "Worlds";if(/^msi/i.test(s))return "MSI";if(/^the international/i.test(s))return "TI";return s.split(/\s+/)[0];};
const PlayerAC=forwardRef(function PlayerAC({value,onChange,allPlayers,onConfirm,activeTourneys={},betFreq={}},fwdRef){
 const [open,setOpen]=useState(false);
 const [inputVal,setInputVal]=useState(value);
 const ref=useRef(null);
 const inputRef=useRef(null);
 const debounceRef=useRef(null);
 const [recents,setRecents]=useState(()=>getRecentPlayers());
 useImperativeHandle(fwdRef,()=>({focus:()=>{if(inputRef.current){inputRef.current.focus();setOpen(true);}}}));

 useEffect(()=>{setInputVal(value);},[value]);

 const isConfirmed=useMemo(()=>{const p=allPlayers[inputVal.toLowerCase().trim()];return !!(p&&String(p.team||"").trim());},[allPlayers,inputVal]);

 const sugg=useMemo(function(){
 const q=inputVal.toLowerCase().trim();
 if(q.length<1){
 // Sans query → joueurs les plus betés en premier (fusion récents + fréquence)
 // Prendre top 8 par fréquence de bets
 const topByFreq=Object.entries(betFreq)
 .filter(([k])=>allPlayers[k]&&String(allPlayers[k].team||"").trim())
 .sort((a,b)=>b[1]-a[1])
 .slice(0,8)
 .map(([k])=>k);
 // Fusionner: récents d'abord, puis top fréquence, dédupliqué
 const merged=[...recents,...topByFreq.filter(k=>!recents.includes(k))].slice(0,7);
 return merged
 .filter(k=>allPlayers[k]&&String(allPlayers[k].team||"").trim())
 .map(k=>[k,allPlayers[k],recents.includes(k)?'recent':'freq']);
 }
 // Agents libres cachés : seuls les joueurs avec un club sont proposés
 const all=Object.entries(allPlayers).filter(([k,p])=>p&&String(p.team||"").trim());
 // Priorité 1: commence par q, trié par fréquence desc (cherche aussi par nom sans préfixe)
 const starts=all
 .filter(([k,p])=>k.startsWith(q)||k.includes(":"+q)||(p.name&&p.name.toLowerCase().startsWith(q)))
 .sort((a,b)=>(betFreq[b[0]]||0)-(betFreq[a[0]]||0));
 // Priorité 2: contient q
 const contains=all
 .filter(([k,p])=>!starts.find(s=>s[0]===k)&&(k.includes(q)||(p.name&&p.name.toLowerCase().includes(q))))
 .sort((a,b)=>(betFreq[b[0]]||0)-(betFreq[a[0]]||0));
 return [...starts,...contains].slice(0,7).map(([k,p])=>[k,p,'search']);
 },[allPlayers,inputVal,recents,betFreq]);

 useEffect(()=>{
 function h(e){if(ref.current&&!ref.current.contains(e.target))setOpen(false);}
 document.addEventListener("mousedown",h);return()=>document.removeEventListener("mousedown",h);
 },[]);

 const handleChange=useCallback(function(e){
 const v=e.target.value;
 setInputVal(v);setOpen(true);
 clearTimeout(debounceRef.current);
 debounceRef.current=setTimeout(()=>{
 onChange(v);
 // Auto-select only if exactly 1 match and not already exact
 const q=v.toLowerCase().trim();
 if(q.length>=2){
 var matches=Object.keys(allPlayers).filter(function(k){return String(k).toLowerCase().includes(q);});
 // Only auto-select if exactly 1 match and input is not already a complete name
 if(matches.length===1&&String(matches[0]).toLowerCase()!==q){
 const key=matches[0];
 setInputVal(key);onChange(key,{confirmed:true});setOpen(false);
 addRecentPlayer(key);setRecents(getRecentPlayers());
 setTimeout(()=>onConfirm&&onConfirm(),60);
 }
 }
 },300);
 },[onChange,allPlayers,onConfirm]);

 const handleSelect=useCallback(function(key){
 setInputVal(key);onChange(key,{confirmed:true});setOpen(false);
 addRecentPlayer(key);
 setRecents(getRecentPlayers());
 // Focus auto sur champ cote après sélection joueur
 setTimeout(()=>onConfirm&&onConfirm(),60);
 },[onChange,onConfirm]);

 return(
 <div ref={ref} style={{position:"relative"}}>
 <div style={{position:"relative"}}>
 <input ref={inputRef} className="add-ifield" placeholder="Rechercher un joueur" value={inputVal} autoComplete="off"
 onChange={handleChange} onFocus={()=>{setRecents(getRecentPlayers());setOpen(true);}}
 style={{paddingRight:isConfirmed?42:14,height:48,background:"transparent",border:"none",outline:"none",borderRadius:0,boxShadow:"none"}}/>
 {isConfirmed&&(
 <div style={{position:"absolute",right:12,top:"50%",transform:"translateY(-50%)",display:"flex",alignItems:"center",justifyContent:"center",width:24,height:24,background:"rgba(34,197,94,0.15)",borderRadius:"50%",border:"1.5px solid #22C55E",pointerEvents:"none"}}>
 <span style={{color:"#22C55E",fontSize:14,lineHeight:1}}><Ic n="check" s={13}/></span>
 </div>
 )}
 </div>
 {open&&sugg.length>0&&(
 <div style={{position:"absolute",top:"calc(100% + 4px)",left:0,right:0,background:"#111827",border:"1px solid #1F2937",borderRadius:10,zIndex:500,overflow:"hidden",boxShadow:"0 8px 28px rgba(0,0,0,0.7)"}}>
 {inputVal.trim().length<1&&<div style={{padding:"8px 13px 4px",fontSize:10.5,color:"#6B7280",fontWeight:700,letterSpacing:.4}}>MES JOUEURS</div>}
 {sugg.map(([key,p,tag])=>{
 const isSelected=key===inputVal.toLowerCase().trim();
 const freq=betFreq[key]||0;
 return(
 <div key={key} onMouseDown={e=>{e.preventDefault();handleSelect(key);}}
 style={{display:"flex",alignItems:"center",gap:9,padding:"9px 13px",cursor:"pointer",borderBottom:"1px solid #1F2937",background:isSelected?"rgba(124,58,237,0.08)":"transparent"}}
 onMouseEnter={e=>e.currentTarget.style.background="rgba(124,58,237,0.1)"}
 onMouseLeave={e=>e.currentTarget.style.background=isSelected?"rgba(124,58,237,0.08)":"transparent"}>
 <Avatar name={p.name||key} game={p.game} size={32}/>
 <div style={{flex:1,minWidth:0}}>
 <div style={{display:"flex",alignItems:"center",gap:6,minWidth:0}}>
 <span style={{fontWeight:750,fontSize:14,color:"#E5E7EB",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{capName(p.name||key)}</span>
 <PosIcon role={p.role} game={p.game} size={14}/>
 </div>
 <div style={{display:"flex",alignItems:"center",gap:5,marginTop:2,minWidth:0,fontSize:11.5,color:"#9CA3AF",whiteSpace:"nowrap"}}>
 {p.team?<><TeamLogo team={p.team} game={p.game} size={15}/><span style={{overflow:"hidden",textOverflow:"ellipsis",color:"#cbd5e1",fontWeight:600}}>{p.team}</span></>:<span style={{color:"#6B7280"}}>Agent libre</span>}
 {p.league&&tourLogoSrc(p.league)&&<span title={p.league} style={{display:"inline-flex",alignItems:"center",flexShrink:0,marginLeft:2}}><LeagueLogo league={p.league} size={15}/></span>}
 </div>
 </div>
 {(()=>{
 const t=activeTourneys[p.game];
 const hasTourney=t&&(!t.end||new Date(t.end)>=new Date());
 return(
 <div style={{display:"flex",gap:4,alignItems:"center"}}>
 {freq>0&&<span style={{fontSize:11.5,fontWeight:800,color:"#c4b5fd",background:"rgba(124,58,237,.12)",border:"1px solid rgba(124,58,237,.25)",padding:"2px 7px",borderRadius:6,fontVariantNumeric:"tabular-nums"}}>{freq}p</span>}
 {isSelected&&<span style={{color:"#22C55E",fontSize:14,fontWeight:700,marginLeft:2}}><Ic n="check" s={13}/></span>}
 </div>
 );
 })()}
 </div>
 );
 })}
 </div>
 )}
 </div>
 );
});




