// Virtualized list for a single day's bets
// Affichage progressif : la suite se rend quand on arrive près du bas (ouverture instantanée des longues listes)
function WhenVisible({onVisible,margin="900px"}){const r=useRef(null);const cb=useRef(onVisible);cb.current=onVisible;
 useEffect(()=>{const el=r.current;if(!el)return;if(typeof IntersectionObserver==="undefined"){cb.current();return;}
  const io=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting))cb.current();},{rootMargin:margin});io.observe(el);return()=>io.disconnect();},[]);
 return <div ref={r} aria-hidden="true" style={{height:1}}/>;}
const VirtualizedDayBets = memo(function VirtualizedDayBets({bets=[], onStatus, onDelete, onDuplicate, onEdit, onSplit, bkPhotos, onSave, allTourneys, savedTourneys}) {
 const [visibleEnd, setVisibleEnd] = useState(20); // hook toujours appelé (règle des hooks)
 if(!bets||bets.length === 0) return null;
 if(bets.length <= 20) {
  return bets.map(b=>(
   <BetRow key={b.id} bet={b} onStatus={onStatus} onDelete={onDelete} onDuplicate={onDuplicate} onEdit={onEdit} onSplit={onSplit} bkPhotos={bkPhotos} onSave={onSave} allTourneys={allTourneys} savedTourneys={savedTourneys}/>
  ));
 }
 // Listes longues : affichage progressif
 return (
  <div>
   {bets.slice(0, visibleEnd).map(b=>(
    <BetRow key={b.id} bet={b} onStatus={onStatus} onDelete={onDelete} onDuplicate={onDuplicate} onEdit={onEdit} onSplit={onSplit} bkPhotos={bkPhotos} onSave={onSave} allTourneys={allTourneys} savedTourneys={savedTourneys}/>
   ))}
   {visibleEnd < bets.length && (
    <div style={{textAlign:"center",padding:"10px 0"}}>
     <button onClick={()=>setVisibleEnd(v=>v+50)} style={{background:"rgba(124,58,237,.15)",border:"1px solid rgba(124,58,237,.3)",borderRadius:8,color:"#a78bfa",padding:"6px 18px",fontSize:12,fontWeight:700,cursor:"pointer",fontFamily:"Inter,sans-serif"}}>
      Voir {Math.min(50, bets.length-visibleEnd)} de plus ({bets.length-visibleEnd} restants)
     </button>
    </div>
   )}
  </div>
 );
});

// Impôt estimé au Québec — travailleur autonome (paris sportifs), barèmes officiels progressifs
// Fédéral (taux le plus bas 14 %) avec abattement du Québec 16,5 %, Québec 2025, RRQ + RQAP autonome,
// puis +2,5 points de marge de sécurité. Profit converti en $ CA à 1,42.
const USD_CAD=1.42, TAX_MARGIN=0.025;
const FED_BRACKETS=[[57375,0.14],[114750,0.205],[177882,0.26],[253414,0.29],[Infinity,0.33]];
const QC_BRACKETS=[[53255,0.14],[106495,0.19],[129590,0.24],[Infinity,0.2575]];
const FED_BPA=16129, QC_BPA=18571;
function progTax(inc,br){let t=0,prev=0;for(const [top,r] of br){if(inc<=prev)break;t+=(Math.min(inc,top)-prev)*r;prev=top;}return t;}
function taxQcBreakdown(usd){
 const cad=Math.max(0,Number(usd)||0)*USD_CAD;
 const rrq=Math.min(Math.max(cad-3500,0),71300-3500)*0.128+Math.min(Math.max(cad-71300,0),81200-71300)*0.08;
 const rqap=Math.min(cad,98000)*0.00878;
 const taxable=Math.max(0,cad-rrq*0.5-rqap*0.44); // part « employeur » déductible
 const fed=Math.max(0,progTax(taxable,FED_BRACKETS)-FED_BPA*0.14)*(1-0.165);
 const qc=Math.max(0,progTax(taxable,QC_BRACKETS)-QC_BPA*0.14);
 const impot=fed+qc, marge=cad*TAX_MARGIN;
 const total=cad>0?impot+rrq+rqap+marge:0;
 return {cad,impot,fed,qc,rrq,rqap,marge,total,rate:cad?total/cad*100:0};
}

