 if(!OD_HEROES){try{const h=await (await fetch("https://api.opendota.com/api/heroes")).json();OD_HEROES={};(h||[]).forEach(x=>OD_HEROES[x.id]=x.localized_name);}catch(e){OD_HEROES={};}}
